export const explorers: PackExplorerWithPortrait[] = [
  { name: "John Bell", birthYear: 1799, deathYear: 1868, nationality: "Scottish",
    biography: "A Mull man who joined the North West Company in 1818 and went to the Mackenzie for the Hudson's Bay Company in 1824, marrying Peter Warren Dease's daughter Nancy, Bell was ordered in 1838 to find a way west from the Mackenzie. He explored the Peel in 1839, built Fort McPherson on it in 1840, crossed the mountains in 1842 and went down the Rat (now the Bell) to the Porcupine, where his guide left him, and in 1845 followed the Porcupine to its meeting with the Yukon, the first company man on the great river. Ill health took him out of the north in 1846; he organized Fort Confidence for Richardson and Rae's Franklin search in 1848-49 and later ran the Athabasca district. He retired to a farm at Saugeen, Ontario.",
    notableAchievements: "Explored the Peel (1839), built Fort McPherson (1840), and in 1845 followed the Porcupine to the Yukon, opening the route by which the Hudson's Bay Company reached the river.",
    guide: [DCB("Bell, John (d. 1868)", "bell_john_1868_9E", "Scholarly biography."), HBCA("Fort McPherson", "Peel River post journals from 1840 and the Mackenzie River district correspondence on the western explorations.")] },
  { name: "Alexander Hunter Murray", birthYear: 1818, deathYear: 1874, nationality: "Scottish", portrait: "Alexander Hunter Murray Fort Yukon",
    biography: "An Argyll Scot who had traded on the upper Missouri for the American Fur Company and sketched its forts, Murray joined the Hudson's Bay Company in 1846, married Anne Campbell at Fort Simpson and wintered at Fort McPherson. On 11 June 1847 he left his bride at Lapierre House on the Bell, went down the Porcupine, reached the Yukon on 25 June and built Fort Yukon just above the junction, a stockaded post with four bastions that he and the company knew stood inside Russian territory. His journal and drawings of 1847-48 are the first record of the Gwich'in of the Yukon flats. In charge until 1851, when his health failed, he later ran Pembina and Lower Fort Garry, and died at his home on the Red River.",
    notableAchievements: "Founded Fort Yukon (1847), the company's farthest post, and kept the Journal of the Yukon, 1847-48, with the first drawings of the Gwich'in.",
    guide: [DCB("Murray, Alexander Hunter", "murray_alexander_hunter_10E", "Scholarly biography."), W("Alexander Hunter Murray", "Alexander_Hunter_Murray", "Life and Fort Yukon."), HBCA("Fort Yukon", "Murray's journal (B.240/a/1-8) and the post's records to 1869.")] },
  { name: "William Lucas Hardisty", birthYear: 1822, deathYear: 1881, nationality: "Canadian (Métis)",
    biography: "Born at Waswanipi House in the Rupert River district, son of a chief trader, Hardisty entered the company in 1842 and was sent to Frances Lake under Robert Campbell in 1843, keeping the post through its hungry winters and trading on the Pelly in 1844-45. He kept Lapierre House on the Bell from 1848, and in 1851 replaced Murray at Fort Yukon, where he opened trade with new Gwich'in bands and experimented with cash trade instead of debt. Chief trader in 1858, he commanded the Mackenzie River district from 1862 to 1878, collected for the Smithsonian with Robert Kennicott, published 'The Loucheux Indians' in 1867, and in 1869 had to manage the American ejection of the company from Fort Yukon. Chief factor in 1868; he retired to Lachine.",
    notableAchievements: "Kept the Yukon posts from Frances Lake to Fort Yukon (1843-1862) and wrote one of the first accounts of the Gwich'in (1867); commanded the Mackenzie River district through the loss of Fort Yukon.",
    guide: [DCB("Hardisty, William Lucas", "hardisty_william_lucas_11E", "Scholarly biography."), HBCA("Fort Yukon", "Hardisty's years in charge, 1851-1862, and the district correspondence of 1869-70 on the American takeover.")] },
  { name: "Frederick Schwatka", birthYear: 1849, deathYear: 1892, nationality: "American", portrait: "Frederick Schwatka",
    biography: "A West Point cavalry officer who also qualified in law and medicine, Schwatka led the American Geographical Society's Franklin search of 1878-80, a 3,251-mile sledge journey with Inuit companions to King William Island that proved no papers survived and that white men could live by Inuit methods. In 1883 the army sent him to reconnoitre the Yukon: with a small party he crossed the Chilkoot Pass, built a raft on the headwater lakes and floated more than 1,300 miles down the whole river to its mouth, naming lakes and rapids as he went, the longest raft journey then recorded. Along Alaska's Great River (1885) made the route famous. He died at Portland of an overdose of the laudanum he took for his stomach.",
    notableAchievements: "First to raft the Yukon from the Chilkoot Pass to the sea (1883) and to publish a popular account of the river; led the 1878-80 Franklin search.",
    guide: [DCB("Schwatka, Frederick", "schwatka_frederick_12E", "Scholarly biography."), W("Frederick Schwatka", "Frederick_Schwatka", "Life and expeditions.")] },
  { name: "Frederick Whymper", birthYear: 1838, deathYear: 1901, nationality: "English",
    biography: "The engraver's son and brother of the Alpinist, Whymper came to Victoria in 1862, sketched the Cariboo and Bute Inlet, drew for the Vancouver Island Exploring Expedition of 1864, and in 1865 joined the Russian-American Telegraph as its artist. After a winter at Nulato on the lower Yukon in 1866-67 he ascended the river by canoe to Fort Yukon, where the news that the Atlantic cable had succeeded ended the project. His Travel and Adventure in the Territory of Alaska (1868), with his drawings, was the first illustrated account of the Yukon in English. He later wrote popular books in London and died there.",
    notableAchievements: "Ascended the Yukon from Nulato to Fort Yukon in 1867 and published the first illustrated account of the river (1868).",
    guide: [DCB("Whymper, Frederick", "whymper_frederick_13E", "Scholarly biography."), W("Frederick Whymper", "Frederick_Whymper", "Life and the Alaska book.")] },
  { name: "George Mercer Dawson", birthYear: 1849, deathYear: 1901, nationality: "Canadian", portrait: "George Mercer Dawson geologist",
    biography: "Son of the principal of McGill, left stunted and hunchbacked by spinal tuberculosis in childhood, Dawson trained at the Royal School of Mines under Huxley, served as geologist of the boundary survey of 1873-74 and joined the Geological Survey of Canada in 1875. In 1887 he led the Yukon expedition: up the Stikine and the Dease to Frances Lake and down the Pelly to the Yukon, then up the headwaters and out over the Chilkoot, fixing points for the Alaska boundary and reading in the glacial gravels the signs of gold to come. Dawson City was named for him in the rush he had foretold, though he never saw the Klondike. Director of the survey from 1895, he died in Ottawa in 1901.",
    notableAchievements: "Led the Yukon Expedition of 1887 up the Stikine and Dease and down the Pelly to the Yukon, and predicted its gold; director of the Geological Survey of Canada (1895-1901).",
    guide: [DCB("Dawson, George Mercer", "dawson_george_mercer_13E", "Scholarly biography."), TCE("George Mercer Dawson", "george-mercer-dawson", "The geologist and the 1887 expedition."), W("George Mercer Dawson", "George_Mercer_Dawson", "Life and work.")] },
  { name: "William Carpenter Bompas", birthYear: 1834, deathYear: 1906, nationality: "English", portrait: "Bishop William Bompas",
    biography: "A London lawyer's clerk turned clergyman, Bompas answered a call for a Yukon missionary in 1865 and walked into Fort Simpson unannounced on Christmas Day, having come from Red River by canoe and snowshoe. He served the Church Missionary Society across the Athabasca and Mackenzie, reached Fort Yukon in 1868 and visited the Inuit of the delta, and in 1874 was made first bishop of Athabasca against his evangelical scruples. Bishop of Mackenzie River in 1884 and of Selkirk, the Yukon, in 1891, he kept his headquarters at Forty Mile and then at Carcross, learned the northern languages, taught, and argued for the Hän and Tagish as the gold rush and the Herschel Island whalers closed in. He died at Carcross in 1906.",
    notableAchievements: "First Anglican bishop of the Yukon (Selkirk, 1891-1905); forty years of travel and teaching among the Dene, Gwich'in, Hän and Tagish.",
    guide: [DCB("Bompas, William Carpenter", "bompas_william_carpenter_13E", "Scholarly biography."), TCE("William Carpenter Bompas", "william-carpenter-bompas", "The bishop of the Yukon."), W("William Carpenter Bompas", "William_Carpenter_Bompas", "Life and dioceses.")] },
  { name: "Charles Constantine", birthYear: 1846, deathYear: 1912, nationality: "Canadian (English-born)", portrait: "Charles Constantine North-West Mounted Police",
    biography: "A Yorkshire-born Manitoba police chief who joined the North-West Mounted Police in 1886, Constantine was sent to the Yukon in 1894 to see what the American miners were doing, collected customs duties to assert Canadian sovereignty, and recommended a force of forty. He came back in July 1895 with twenty men, built Fort Constantine at Forty Mile, the first police post in the territory, and as acting commissioner recorded George Carmack's discovery claim on 24 September 1896 and the claims of Keish and Káa Goox beside it. He negotiated with Chief Isaac and Bishop Bompas the Hän's move to Moosehide in 1897, left the Yukon in 1898, and later opened the Fort McPherson and Herschel Island detachments and built the Peace-Yukon trail.",
    notableAchievements: "Brought the first North-West Mounted Police detachment to the Yukon and built Fort Constantine at Forty Mile (1895); recorded the Klondike discovery claims (1896).",
    guide: [DCB("Constantine, Charles", "constantine_charles_14E", "Scholarly biography."), W("Charles Constantine", "Charles_Constantine", "The first Mountie in the Yukon.")] },
  { name: "Sam Steele", birthYear: 1848, deathYear: 1919, nationality: "Canadian", portrait: "Sam Steele North-West Mounted Police",
    biography: "The Ontario militiaman who marched west with the Mounted Police in 1874, Steele was ordered to the Yukon in January 1898 to set up the customs posts at the summits of the White and Chilkoot passes and at Bennett Lake, where thirty thousand stampeders were building boats. At Bennett that spring he made every boat register and obey his rules of navigation before running Miles Canyon, and in July took command of all the police in the Yukon and a seat on the territorial council. He moved to Dawson in September and ran the town's law until September 1899, when he was transferred, by his own account for resisting Clifford Sifton's patronage, and the miners gave him a bag of gold dust. He later commanded Strathcona's Horse in South Africa and a division in the First World War.",
    notableAchievements: "Commanded the North-West Mounted Police in the Yukon through the gold rush (1898-99), from the pass summits and Bennett Lake to Dawson.",
    guide: [DCB("Steele, Sir Samuel Benfield", "steele_samuel_benfield_14E", "Scholarly biography."), W("Sam Steele", "Sam_Steele", "The policeman of the Klondike."), IA("Forty Years in Canada", "Samuel Benfield Steele", "1915", "fortyyearsincana00steerich", "His autobiography, with the Yukon chapters.")] },
  { name: "Lavrenty Zagoskin", birthYear: 1808, deathYear: 1890, nationality: "Russian",
    biography: "A Russian naval officer from Penza, trained in natural history, who proposed and led the Russian-American Company's reconnaissance of the Alaskan interior in 1842-44 to find sites for posts and the sources of the furs the Natives traded to the coast. In 1842 and 1843 he travelled the lower Yukon, the Kuskokwim, the Innoko and the Koyukuk, the first European survey of the lower river. His account, published in St. Petersburg, is the beginning of the Yukon's written record from the Bering Sea side.",
    notableAchievements: "First European survey of the lower Yukon and the Kuskokwim (1842-44); author of the first published account of the Alaskan interior.",
    guide: [W("Lavrenty Zagoskin", "Lavrenty_Zagoskin", "Life and the 1842-44 reconnaissance.")] },
  { name: "Robert Kennicott", birthYear: 1835, deathYear: 1866, nationality: "American",
    biography: "An Illinois naturalist who collected for the Smithsonian from boyhood, founded the Chicago Academy of Sciences and taught William Healey Dall, Kennicott went north in 1859 to the Hudson's Bay Company's Mackenzie and Yukon posts, where William Hardisty and other traders collected birds and specimens for him; the company's men became the Smithsonian's correspondents for a generation. In 1865 he led the scientific corps of the Western Union Telegraph Expedition to Alaska and died on the Yukon in Alaska in May 1866, aged thirty. The Kennicott Glacier is named for him.",
    notableAchievements: "Opened the Hudson's Bay Company's northern posts to the Smithsonian's natural-history collecting (1859-62); chief scientist of the Western Union Telegraph Expedition; died on the Yukon (1866).",
    guide: [W("Robert Kennicott", "Robert_Kennicott", "Life and the northern collecting."), DCB("Hardisty, William Lucas", "hardisty_william_lucas_11E", "The trader who collected with him.")] },
  { name: "Jack McQuesten", birthYear: 1836, deathYear: 1909, nationality: "American", portrait: "Jack McQuesten Yukon",
    biography: "Leroy Napoleon McQuesten, a New Hampshire man who had gone to the California diggings as a boy, came into the Yukon in 1871 and with Arthur Harper and Alfred Mayo built the trading posts that fed the river's first prospectors: Fort Reliance below the Klondike's mouth in 1875, Forty Mile in 1886 and others for the Alaska Commercial Company, grubstaking miners on credit so freely that they called him the Father of the Yukon. Rich by 1898, he retired to Berkeley, California, and his Recollections of life on the river from 1871 to 1885 were printed after his death.",
    notableAchievements: "Built Fort Reliance (1875) and Forty Mile (1886), the trading posts of the pre-Klondike Yukon, and grubstaked its prospectors; 'Father of the Yukon'.",
    guide: [W("Jack McQuesten", "Jack_McQuesten", "Life and the Yukon posts."), W("Forty Mile, Yukon", "Forty_Mile,_Yukon", "The town he and his partners founded.")] },
  { name: "Arthur Harper", birthYear: 1835, deathYear: 1897, nationality: "Irish (American)",
    biography: "An Irish-born miner of California and the Cariboo who reasoned that the gold of British Columbia must continue north into the Yukon and went to find it, reaching Fort Yukon in 1873. The best prospector of the McQuesten-Harper-Mayo partnership and the least lucky, he traded at Fort Reliance, Forty Mile and Fort Selkirk, pointed others toward the creeks that paid, and died of tuberculosis in Arizona in 1897, the year the Klondike he had predicted made everyone else rich. He had married Seentahna, whom he called Jennie, at Koyukuk in 1874; they separated in 1895.",
    notableAchievements: "First to enter the Yukon seeking gold (1871-73); partner in the trading posts of the pre-Klondike river.",
    guide: [W("Arthur Harper (trader)", "Arthur_Harper_(trader)", "Life and the Yukon partnership."), W("Jack McQuesten", "Jack_McQuesten", "His partner's story.")] },
  { name: "William Ogilvie", birthYear: 1846, deathYear: 1912, nationality: "Canadian", portrait: "William Ogilvie surveyor Yukon",
    biography: "A Dominion land surveyor from the Ottawa valley who had worked the prairies since 1875, Ogilvie went north with Dawson's Yukon Expedition in 1887, surveyed the Chilkoot Pass and the Yukon and fixed the 141st meridian, the Alaska boundary, on the river near Forty Mile in 1887-88, and came back to the river in the 1890s. He surveyed the Klondike claims after the discovery, settling the disputes of the first winter, and was commissioner of the Yukon from 1898. His Early Days on the Yukon (1913) is the surveyor's account of the river before and during the rush.",
    notableAchievements: "Surveyed the Chilkoot Pass and fixed the Alaska boundary on the Yukon at the 141st meridian (1887-88); surveyed the Klondike claims (1896-97); commissioner of the Yukon from 1898.",
    guide: [TCE("William Ogilvie", "william-ogilvie", "The surveyor and commissioner."), W("William Ogilvie (surveyor)", "William_Ogilvie_(surveyor)", "Life and surveys."), IA("Early Days on the Yukon", "William Ogilvie", "1913", "earlydaysonyukon00ogiluoft", "His own account.")] },
  { name: "George Carmack", birthYear: 1860, deathYear: 1922, nationality: "American", portrait: "George Carmack",
    biography: "A Californian who deserted the Marines in 1882 and came to the Yukon in 1885 to trade, fish and trap, Carmack packed on the Chilkoot with Keish and Káa Goox, lived with Keish's sister Shaaw Tláa from 1887, found coal at the place now called Carmacks and was known to the miners as Lyin' George. In August 1896, fishing at the Klondike's mouth when his wife's brother found him, he went up Rabbit Creek with Keish and Charlie and, on 16 August, gold was found; he staked the discovery claim and the double claim beside it on 24 September and took the credit for sixty years. Rich, he left Kate in 1900 for a Dawson woman and died in Vancouver in 1922.",
    notableAchievements: "Staked the Discovery Claim on Bonanza Creek (1896) with Keish and Káa Goox, the start of the Klondike gold rush.",
    guide: [W("George Carmack", "George_Carmack", "Life and the discovery."), DCB("Keish (Skookum Jim, James Mason)", "keish_14E", "The discovery from the Tagish side."), IA("My Experiences in the Yukon", "George W. Carmack", "1933", "myexperiencesiny00carm", "His own short account.")] },
  { name: "Joseph Ladue", birthYear: 1855, deathYear: 1901, nationality: "American",
    biography: "A New York State man who had mined at Deadwood and in the Southwest, Ladue crossed the Chilkoot in 1882 and traded and prospected on the Yukon for fourteen years, running a sawmill and a trading post. Days after the discovery of August 1896 he staked the boggy flat at the Klondike's mouth as a townsite, moved his mill there and named the town Dawson, after the geologist, in January 1897; by July five thousand people lived on his lots, which sold for thousands of dollars each. He died of tuberculosis in 1901.",
    notableAchievements: "Founded Dawson City on the Klondike's mouth (1896-97).",
    guide: [W("Joseph Ladue", "Joseph_Ladue", "Life and the founding of Dawson."), TCE("Dawson", "dawson", "The town he laid out.")] },
];

